def transform(grid):
    """Vertically align each same-shaped colored object with the color-8 object."""
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(w)] for _ in range(h)]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            objects.append((color, cells))
    anchor_top = min(y for color, cells in objects if color == 8 for y, _ in cells)
    for color, cells in objects:
        top = min(y for y, _ in cells)
        shift = anchor_top - top
        for y, x in cells:
            ny = y + shift
            if 0 <= ny < h:
                out[ny][x] = color
    return out
